package energy;/** * EU能量存储实现类 * <p> * 提供EUEnergyStorage接口的基本实现，支持NBT序列化。 * 适用于方块实体的能量存储组件。 * </p> */public class EUEnergyStorageImpl implements EUEnergyStorage {    /** 当前存储的能量 */    protected long energy;    /** 最大存储容量 */    protected final long capacity;    /** 最大接收速率 */    protected final long maxReceive;    /** 最大提取速率 */    protected final long maxExtract;    /** 运行电压等级 */    protected final EUVoltage voltage;    /**     * 创建能量存储实例     *     * @param capacity   最大容量 (EU)     * @param maxReceive 最大接收速率 (EU/t)     * @param maxExtract 最大提取速率 (EU/t)     * @param voltage    运行电压等级     */    public EUEnergyStorageImpl(long capacity, long maxReceive, long maxExtract, EUVoltage voltage) {        this.capacity = capacity;        this.maxReceive = maxReceive;        this.maxExtract = maxExtract;        this.voltage = voltage;    }    /**     * 创建能量存储实例（接收和提取速率相同）     *     * @param capacity 最大容量 (EU)     * @param maxRate  最大传输速率 (EU/t)     * @param voltage  运行电压等级     */    public EUEnergyStorageImpl(long capacity, long maxRate, EUVoltage voltage) {        this(capacity, maxRate, maxRate, voltage);    }    /**     * 创建能量存储实例（使用电压等级默认速率）     *     * @param capacity 最大容量 (EU)     * @param voltage  运行电压等级     */    public EUEnergyStorageImpl(long capacity, EUVoltage voltage) {        this(capacity, voltage.getMaxVoltage(), voltage.getMaxVoltage(), voltage);    }    @Override    public long receiveEnergy(long maxReceive, boolean simulate) {        if (!canReceive()) return 0;        long received = Math.min(maxReceive, this.maxReceive);        received = Math.min(received, capacity - energy);        if (!simulate) {            energy += received;        }        return received;    }    @Override    public long extractEnergy(long maxExtract, boolean simulate) {        if (!canExtract()) return 0;        long extracted = Math.min(maxExtract, this.maxExtract);        extracted = Math.min(extracted, energy);        if (!simulate) {            energy -= extracted;        }        return extracted;    }    @Override    public long getEnergyStored() {        return energy;    }    @Override    public long getMaxEnergyStored() {        return capacity;    }    @Override    public EUVoltage getVoltage() {        return voltage;    }    @Override    public long getMaxTransferRate() {        return Math.max(maxReceive, maxExtract);    }    /**     * 直接设置能量值（用于NBT加载）     *     * @param energy 能量值     */    public void setEnergy(long energy) {        this.energy = Math.max(0, Math.min(energy, capacity));    }    /**     * 从NBT标签读取数据     *     * @param energyTag 包含能量数据的long值     */    public void readFromNBT(long energyTag) {        this.energy = Math.max(0, Math.min(energyTag, capacity));    }    /**     * 将能量数据写入NBT     *     * @return 能量值用于NBT存储     */    public long writeToNBT() {        return energy;    }    /**     * 添加能量（不检查接收限制）     *     * @param amount 要添加的能量     * @return 实际添加的能量     */    public long addEnergy(long amount) {        long added = Math.min(amount, capacity - energy);        energy += added;        return added;    }    /**     * 移除能量（不检查提取限制）     *     * @param amount 要移除的能量     * @return 实际移除的能量     */    public long removeEnergy(long amount) {        long removed = Math.min(amount, energy);        energy -= removed;        return removed;    }    /**     * 清空所有能量     */    public void clearEnergy() {        this.energy = 0;    }    @Override    public String toString() {        return String.format("EUEnergyStorage[%d/%d EU, %s]", energy, capacity, voltage.getName());    }}